                            ok: false;
                            /** @description The provider id from the path. */
                            provider: string;
                            /** @enum {string} */
                            error: "verify_unsupported";
                            /** @description A CodeSpar-authored sentence naming this provider, not provider text. No outbound call was made on this branch, which is why there is no `status` and no `latency_ms`. */
                            detail?: string;
